<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import * as XLSX from 'xlsx'
import { CalendarDays, Check, ClipboardCheck, Download, Menu, MessageSquare, Pencil, Plus, Save, Settings, Trash2, Users, X } from 'lucide-vue-next'
import { buildExportCell, createExportVersion } from './domain/export'
import { getBasePlannedShift, type Shift } from './domain/schedule'
import { addStatusOption, ensureDailyRecord, removeStatusOption, submitDailyRecord, updateEntryActualShift, updateEntryNote, updateEntryStatus, updateGroupNote, type ActualStatus, type AttendanceEntry, type DailyRecord, type StatusOption } from './domain/workbench'
import { createBrowserStateStore } from './storage/browser-state'

type View = 'ledger' | 'people'
type GroupId = 'jia' | 'yi' | 'bing' | 'ding' | 'changbai'
interface Group { id: GroupId; name: string; referencePosition?: number; scheduleType: 'rotating' | 'weekday' }
interface Person { id: string; name: string; groupId: GroupId; activeFrom: string }
interface StoredState { groups: Group[]; people: Person[]; records: DailyRecord[]; rotationReferenceDate: string; statusOptions: StatusOption[] }
const today = '2026-11-13'; const month = '2026-11'; const storageKey = 'blower-station-attendance-v10'; const defaultCycle: Shift[] = ['night','night','day','day','swing','swing','rest','rest']
const seedGroups: Group[] = [{ id:'jia',name:'甲班',referencePosition:3,scheduleType:'rotating'},{ id:'yi',name:'乙班',referencePosition:7,scheduleType:'rotating'},{ id:'bing',name:'丙班',referencePosition:1,scheduleType:'rotating'},{ id:'ding',name:'丁班',referencePosition:5,scheduleType:'rotating'},{ id:'changbai',name:'长白班',scheduleType:'weekday'}]
const seedPeople: Person[] = ([['jia','张兰琦'],['jia','郭志旗'],['jia','刘高星'],['jia','董嘉伦'],['yi','崔燕军'],['yi','谢敏'],['yi','刘兆强'],['yi','张世杰'],['bing','申趁安'],['bing','范胜利'],['bing','田家俊'],['bing','张浩'],['ding','刘宪军'],['ding','敦东只'],['ding','郝哲'],['ding','惠泽'],['changbai','郭成立']] as [GroupId,string][]).map(([groupId,name],index) => ({ id:`${groupId}-${index + 1}`, name, groupId, activeFrom:'2026-01-01'}))
const defaultStatusOptions: StatusOption[] = [{value:'normal',label:'正常出勤'},{value:'personal-leave',label:'事假'},{value:'sick-leave',label:'病假'},{value:'monthly-leave',label:'月休'},{value:'annual-leave',label:'年休假'},{value:'absent',label:'旷工'},{value:'swap',label:'调班'},{value:'time-off',label:'调休'},{value:'top-up',label:'顶班'}]
function createDefaultState():StoredState{return {groups:seedGroups.map(group=>({...group})),people:seedPeople.map(person=>({...person})),records:[],rotationReferenceDate:'2026-11-01',statusOptions:defaultStatusOptions.map(option=>({...option}))}}
function isStoredState(value:unknown):value is StoredState {if(typeof value!=='object'||value===null)return false;const state=value as Record<string,unknown>;return Array.isArray(state.groups)&&Array.isArray(state.people)&&Array.isArray(state.records)&&typeof state.rotationReferenceDate==='string'&&Array.isArray(state.statusOptions)}
const stateStore=createBrowserStateStore({storage:window.localStorage,key:storageKey,legacyKeys:[],version:1,createDefaultState,isState:isStoredState})
const data=stateStore.load(); const groups=ref(data.groups); const people=ref(data.people); const records=ref(data.records); const rotationReferenceDate=ref(data.rotationReferenceDate); const statusOptions=ref([...data.statusOptions,...defaultStatusOptions.filter(option=>!data.statusOptions.some(saved=>saved.value===option.value))])
const currentView=ref<View>('ledger'); const mobileOpen=ref(false); const selectedGroupId=ref<GroupId>('jia'); const toast=ref(''); const personModal=ref(false); const editPersonId=ref<string | null>(null); const personForm=ref({name:'',groupId:'jia' as GroupId,activeFrom:today}); const groupModal=ref(false); const groupDraft=ref<Group[]>([]); const statusModal=ref(false); const newStatusLabel=ref(''); const entryNoteModal=ref(false); const notedEntry=ref<AttendanceEntry | null>(null); const entryNoteText=ref(''); const ledgerEditorModal=ref(false); const ledgerPerson=ref<Person | null>(null); const ledgerDate=ref(''); const ledgerStatus=ref<ActualStatus>('normal'); const ledgerActualShift=ref<Shift | undefined>()
const selectedGroup=computed(() => groups.value.find(group => group.id===selectedGroupId.value)!); const days=Array.from({length:30},(_,i)=>i+1)
function planned(groupId:GroupId,_personId:string,date:string):Shift { const group=groups.value.find(item=>item.id===groupId)!; return getBasePlannedShift({group,referenceDate:rotationReferenceDate.value,date}) }
function record(groupId:GroupId,date:string):DailyRecord { const workbench=ensureDailyRecord({records:records.value,groupId,date,people:people.value,plannedShift:(personId)=>planned(groupId,personId,date)}); if(workbench.records!==records.value) records.value=workbench.records; return workbench.record }
const activeRecord=computed(() => record(selectedGroupId.value,today)); const activeEntries=computed(() => activeRecord.value.entries)
watch([groups,people,records,rotationReferenceDate,statusOptions],()=>stateStore.save({groups:groups.value,people:people.value,records:records.value,rotationReferenceDate:rotationReferenceDate.value,statusOptions:statusOptions.value}),{deep:true})
function shiftLabel(shift:Shift){return {night:'夜班 00:00-08:00',day:'白班 08:00-16:00',swing:'中班 16:00-24:00',rest:'休息'}[shift]}; function shiftCode(shift:Shift){return {night:'夜',day:'√',swing:'中',rest:'休'}[shift]}; function phaseLabel(position?:number){return ({1:'夜班第1天',2:'夜班第2天',3:'白班第1天',4:'白班第2天',5:'中班第1天',6:'中班第2天',7:'休息第1天',8:'休息第2天'} as Record<number,string>)[position??0]}; function state(status:DailyRecord['status']){return {draft:'待提交',submitted:'待核对',confirmed:'已确认'}[status]}; function canEdit(){return true}; function notify(text:string){toast.value=text;window.setTimeout(()=>{if(toast.value===text)toast.value=''},2600)}
function replaceRecords(result:{ok:true;value:DailyRecord[]}|{ok:false;message:string}){if(!result.ok){notify(result.message);return false}records.value=result.value;return true}; function submit(){if(replaceRecords(submitDailyRecord({records:records.value,groupId:selectedGroupId.value,date:today})))notify(`${selectedGroup.value.name} 考勤已提交`)}; function change(entry:AttendanceEntry,status:ActualStatus){replaceRecords(updateEntryStatus({records:records.value,groupId:selectedGroupId.value,date:today,personId:entry.personId,status}))}; function changeActualShift(entry:AttendanceEntry,actualShift:Shift|undefined){replaceRecords(updateEntryActualShift({records:records.value,groupId:selectedGroupId.value,date:today,personId:entry.personId,actualShift}))}; function openEntryNote(entry:AttendanceEntry){notedEntry.value=entry;entryNoteText.value=entry.note;entryNoteModal.value=true}; function saveEntryNote(){if(!notedEntry.value)return;if(replaceRecords(updateEntryNote({records:records.value,groupId:selectedGroupId.value,date:today,personId:notedEntry.value.personId,note:entryNoteText.value}))){entryNoteModal.value=false;notify('个人备注已保存')}}; function saveGroupNote(note:string){replaceRecords(updateGroupNote({records:records.value,groupId:selectedGroupId.value,date:today,note}))}; function addStatus(){const result=addStatusOption(statusOptions.value,newStatusLabel.value,`custom-${Date.now()}`);if(!result.ok)return notify(result.message);statusOptions.value=result.value;newStatusLabel.value='';notify('今日考勤状态已新增')}; function removeStatus(option:StatusOption){const result=removeStatusOption({records:records.value,options:statusOptions.value,value:option.value});if(!result.ok)return notify(result.message);records.value=result.value.records;statusOptions.value=result.value.options;notify(`已删除“${option.label}”状态`) }
function openPerson(person?:Person){editPersonId.value=person?.id??null;personForm.value=person?{name:person.name,groupId:person.groupId,activeFrom:person.activeFrom}:{name:'',groupId:selectedGroupId.value,activeFrom:today};personModal.value=true}; function savePerson(){const name=personForm.value.name.trim();if(!name)return notify('请填写姓名');if(editPersonId.value)Object.assign(people.value.find(item=>item.id===editPersonId.value)!,{...personForm.value,name});else people.value.push({...personForm.value,name,id:`${personForm.value.groupId}-${Date.now()}`});personModal.value=false;notify('人员信息已保存')}
function removePerson(person:Person){if(!window.confirm(`确认删除 ${person.name} 吗？该人员的既有考勤记录不会删除。`))return;people.value.splice(people.value.findIndex(item=>item.id===person.id),1);notify(`${person.name} 已删除`)}; function openGroups(){groupDraft.value=groups.value.map(group=>({...group}));groupModal.value=true}; function saveGroups(){const rotating=groupDraft.value.filter(group=>group.scheduleType==='rotating');const positions=rotating.map(group=>group.referencePosition);const validFirstDay=positions.slice().sort((a,b)=>a!-b!).join(',')==='1,3,5,7';const validSecondDay=positions.slice().sort((a,b)=>a!-b!).join(',')==='2,4,6,8';if(!validFirstDay&&!validSecondDay)return notify('四个轮班需分别选择夜、白、中、休的同一阶段');groups.value.splice(0,groups.value.length,...groupDraft.value);groupModal.value=false;notify('排班基准已保存')}
function ledgerEntry(person:Person,day:number){const date=`${month}-${String(day).padStart(2,'0')}`;return records.value.find(item=>item.groupId===person.groupId&&item.date===date)?.entries.find(item=>item.personId===person.id)}; function statusCode(status:ActualStatus){const label=statusOptions.value.find(option=>option.value===status)?.label.trim()??status.trim();return label.slice(0,1)||'异'}; function cell(person:Person,day:number){const entry=ledgerEntry(person,day);if(!entry)return buildExportCell({plannedShift:planned(person.groupId,person.id,`${month}-${String(day).padStart(2,'0')}`),actualStatus:'normal'});return entry.status==='normal'?buildExportCell({plannedShift:entry.planned,actualStatus:entry.status,actualShift:entry.actualShift}):statusCode(entry.status)}; function isException(person:Person,day:number){const entry=ledgerEntry(person,day);return Boolean(entry&&entry.status!=='normal')}; function openLedgerEditor(person:Person,day:number){const date=`${month}-${String(day).padStart(2,'0')}`;const entry=record(person.groupId,date).entries.find(item=>item.personId===person.id);if(!entry)return;ledgerPerson.value=person;ledgerDate.value=date;ledgerStatus.value=entry.status;ledgerActualShift.value=entry.actualShift;ledgerEditorModal.value=true}; function saveLedgerStatus(){const person=ledgerPerson.value;if(!person)return;const updated=updateEntryStatus({records:records.value,groupId:person.groupId,date:ledgerDate.value,personId:person.id,status:ledgerStatus.value});if(!updated.ok)return notify(updated.message);let next=updated.value;if(ledgerStatus.value==='swap'||ledgerStatus.value==='top-up'){const shifted=updateEntryActualShift({records:next,groupId:person.groupId,date:ledgerDate.value,personId:person.id,actualShift:ledgerActualShift.value});if(!shifted.ok)return notify(shifted.message);next=shifted.value}records.value=next;ledgerEditorModal.value=false;notify(`${person.name} ${ledgerDate.value} 考勤已更新`)}; function exportMonthlyLedger(){const version=createExportVersion(month,1);const filename=`鼓风站考勤表-${version}.xlsx`;try{const rows:(string|number)[][]=[['鼓风站考勤表'],[`月份：${month}`],[`导出版本：${version}`],[],['班组','姓名',...days]];for(const group of groups.value){for(const person of people.value.filter(item=>item.groupId===group.id)){rows.push([group.name,person.name,...days.map(day=>cell(person,day))])}}const sheet=XLSX.utils.aoa_to_sheet(rows);sheet['!merges']=[{s:{r:0,c:0},e:{r:0,c:days.length+1}}];sheet['!cols']=[{wch:12},{wch:12},...days.map(()=>({wch:5}))];const workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,sheet,`${month}台账`);const content=XLSX.write(workbook,{bookType:'xlsx',type:'array'});const url=URL.createObjectURL(new Blob([content],{type:'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'}));const link=document.createElement('a');link.href=url;link.download=filename;document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>URL.revokeObjectURL(url),0);notify(`已下载 ${filename}`)}catch(error){console.error('Excel export failed',error);notify('Excel 导出失败，请稍后重试')}}
</script>

<template>
  <div class="shell">
    <header class="topbar"><div class="brand"><div class="brand-mark"><ClipboardCheck :size="22" /></div><div><strong>鼓风站考勤</strong><span>动力部 · 管理工作台</span></div></div><div class="topbar-actions"><span class="today-label">2026年11月13日 · 星期五</span><button class="icon-button mobile-only" type="button" @click="mobileOpen=!mobileOpen"><Menu :size="20" /></button></div></header>
    <aside class="sidebar" :class="{open:mobileOpen}"><nav><button :class="{active:currentView==='ledger'}" @click="currentView='ledger';mobileOpen=false"><CalendarDays :size="18" />月度台账</button><button :class="{active:currentView==='people'}" @click="currentView='people';mobileOpen=false"><Users :size="18" />人员与班组</button></nav></aside>
    <main class="content">
      <section v-if="currentView==='ledger'" class="view"><div class="view-heading"><div><p class="eyebrow">月度考勤</p><h1>2026 年 11 月考勤台账</h1><p>版本 {{createExportVersion(month,1)}} · 当前为电子工作台账</p></div><button class="primary-button" @click="exportMonthlyLedger"><Download :size="17" />导出 Excel</button></div><section class="panel ledger-panel"><div class="ledger-toolbar"><div class="filter-group"><label>班组<select v-model="selectedGroupId"><option v-for="group in groups" :key="group.id" :value="group.id">{{group.name}}</option></select></label></div></div><div class="ledger-scroll"><table class="ledger-table"><thead><tr><th class="freeze">姓名</th><th v-for="day in days" :key="day">{{day}}</th></tr></thead><tbody><tr v-for="person in people.filter(item=>item.groupId===selectedGroupId)" :key="person.id"><th class="freeze"><strong>{{person.name}}</strong><small>{{selectedGroup.name}}</small></th><td v-for="day in days" :key="day" :class="{ 'note-cell': Boolean(ledgerEntry(person,day)?.note), exception: isException(person,day), 'clickable-note': true }" title="编辑当天考勤" @click="openLedgerEditor(person,day)">{{cell(person,day)}}</td></tr></tbody></table></div><div class="ledger-footer"><span>点击任意日期单元格可直接修改当天考勤状态，非正常状态以红字显示</span></div></section><section class="workbench"><div class="panel group-workbench"><div class="panel-heading"><div><p class="eyebrow">管理员登记</p><h2>{{selectedGroup.name}} · 当日登记</h2><p>{{today}} · {{shiftLabel(planned(selectedGroup.id,`${selectedGroup.id}-1`,today))}}</p></div><div class="heading-actions"><button class="icon-button" title="维护今日考勤状态" @click="statusModal=true"><Settings :size="16" /></button></div></div><div class="member-editor"><div v-for="entry in activeEntries" :key="entry.personId" class="member-row"><div><strong>{{people.find(person=>person.id===entry.personId)?.name}}</strong><span>计划 {{shiftCode(entry.planned)}}{{entry.note?' · 已备注':''}}</span></div><select :value="entry.status" :disabled="!canEdit()" @change="change(entry,($event.target as HTMLSelectElement).value as ActualStatus)"><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{option.label}}</option></select><button class="icon-button" :class="{ 'has-note': entry.note }" :disabled="!canEdit()" title="添加个人备注" @click="openEntryNote(entry)"><MessageSquare :size="16" /></button><select v-if="entry.status==='swap'||entry.status==='top-up'" :value="entry.actualShift" :disabled="!canEdit()" @change="changeActualShift(entry,($event.target as HTMLSelectElement).value as Shift)"><option value="night">夜</option><option value="day">√</option><option value="swing">中</option></select></div></div><label class="attendance-note">班组备注<textarea :value="activeRecord.note" :disabled="!canEdit()" placeholder="填写当日班组情况、交接事项或需要管理员留意的内容" @change="saveGroupNote(($event.target as HTMLTextAreaElement).value)"></textarea></label><div class="panel-footer"><span>当前状态：<b>{{state(activeRecord.status)}}</b></span><button class="primary-button" :disabled="!canEdit()" @click="submit"><Check :size="17" />提交当日考勤</button></div></div></section></section>
      <section v-else class="view"><div class="view-heading"><div><p class="eyebrow">主数据</p><h1>人员与班组</h1><p>人员变动从完整考勤日期生效，同一人同日只归属一个主班组。</p></div><div class="heading-actions"><button class="secondary-button" @click="openGroups"><Pencil :size="16" />设置排班基准</button><button class="primary-button" @click="openPerson()"><Plus :size="17" />新增人员</button></div></div><section class="panel rotation-panel"><div class="panel-heading"><div><h2>四班排班基准</h2><p>参考日期 {{rotationReferenceDate}}：丙班夜、甲班白、丁班中、乙班休。系统据此自动循环“夜夜白白中中休休”。</p></div></div><div class="rotation-order"><div v-for="group in groups.filter(item=>item.scheduleType==='rotating')" :key="group.id"><i class="group-dot" :class="group.id"></i><strong>{{group.name}}</strong><small>{{phaseLabel(group.referencePosition)}}</small></div></div></section><section class="panel people-panel"><div v-for="group in groups" :key="group.id" class="people-group"><div class="people-group-title"><span><i class="group-dot" :class="group.id"></i>{{group.name}}</span><small>{{group.scheduleType==='weekday'?'法定工作日':phaseLabel(group.referencePosition)}}</small></div><div v-for="person in people.filter(item=>item.groupId===group.id)" :key="person.id" class="person-row"><div class="avatar">{{person.name.slice(0,1)}}</div><strong>{{person.name}}</strong><span>在岗 · {{person.activeFrom}} 起</span><button class="icon-button" title="编辑人员" @click="openPerson(person)"><Pencil :size="16" /></button><button class="icon-button danger-button" title="删除人员" @click="removePerson(person)"><X :size="16" /></button></div></div></section></section>
    </main>
    <div v-if="personModal" class="modal-backdrop"><form class="modal" @submit.prevent="savePerson"><div class="panel-heading"><h2>{{editPersonId?'修改人员':'新增人员'}}</h2><button class="icon-button" type="button" @click="personModal=false"><X :size="16" /></button></div><label class="field-label">姓名<input v-model="personForm.name" autofocus /></label><label class="field-label">所属班组<select v-model="personForm.groupId"><option v-for="group in groups" :key="group.id" :value="group.id">{{group.name}}</option></select></label><label class="field-label">生效日期<input v-model="personForm.activeFrom" type="date" /></label><div class="form-actions"><button class="secondary-button" type="button" @click="personModal=false">取消</button><button class="primary-button" type="submit"><Save :size="16" />保存</button></div></form></div>
    <div v-if="groupModal" class="modal-backdrop"><form class="modal" @submit.prevent="saveGroups"><div class="panel-heading"><h2>设置排班基准</h2><button class="icon-button" type="button" @click="groupModal=false"><X :size="16" /></button></div><p class="modal-note">选择一个你能确认当日各班班次的日期，再直接填写当天四班处于哪一段。无需计算各班夜班日期，系统会自动推算以后所有班次。</p><label class="field-label">参考日期<input v-model="rotationReferenceDate" type="date" /></label><div v-for="group in groupDraft" :key="group.id" class="group-form-row"><i class="group-dot" :class="group.id"></i><input v-model="group.name" /><label v-if="group.scheduleType==='rotating'">当天班次阶段<select v-model.number="group.referencePosition"><option :value="1">夜班第1天</option><option :value="2">夜班第2天</option><option :value="3">白班第1天</option><option :value="4">白班第2天</option><option :value="5">中班第1天</option><option :value="6">中班第2天</option><option :value="7">休息第1天</option><option :value="8">休息第2天</option></select></label><span v-else class="weekday-note">法定工作日：√ / 休</span></div><div class="form-actions"><button class="secondary-button" type="button" @click="groupModal=false">取消</button><button class="primary-button" type="submit"><Save :size="16" />保存排班基准</button></div></form></div>
    <div v-if="entryNoteModal" class="modal-backdrop"><form class="modal" @submit.prevent="saveEntryNote"><div class="panel-heading"><h2>个人备注</h2><button class="icon-button" type="button" @click="entryNoteModal=false"><X :size="16" /></button></div><p class="modal-note">{{people.find(person=>person.id===notedEntry?.personId)?.name}} · {{selectedGroup.name}} · {{today}}</p><label class="field-label">备注内容<textarea v-model="entryNoteText" placeholder="例如：设备检修协助、外出培训、交接说明"></textarea></label><div class="form-actions"><button class="secondary-button" type="button" @click="entryNoteModal=false">取消</button><button class="primary-button" type="submit"><Save :size="16" />保存备注</button></div></form></div>
    <div v-if="ledgerEditorModal" class="modal-backdrop"><form class="modal" @submit.prevent="saveLedgerStatus"><div class="panel-heading"><h2>修改当天考勤</h2><button class="icon-button" type="button" @click="ledgerEditorModal=false"><X :size="16" /></button></div><p class="modal-note">{{ledgerPerson?.name}} · {{ledgerDate}}</p><label class="field-label">考勤状态<select v-model="ledgerStatus"><option v-for="option in statusOptions" :key="option.value" :value="option.value">{{option.label}}</option></select></label><label v-if="ledgerStatus==='swap'||ledgerStatus==='top-up'" class="field-label">实际班次<select v-model="ledgerActualShift"><option value="night">夜班 00:00-08:00</option><option value="day">白班 08:00-16:00</option><option value="swing">中班 16:00-24:00</option></select></label><div class="form-actions"><button class="secondary-button" type="button" @click="ledgerEditorModal=false">取消</button><button class="primary-button" type="submit"><Save :size="16" />保存</button></div></form></div>
    <div v-if="statusModal" class="modal-backdrop"><form class="modal" @submit.prevent="addStatus"><div class="panel-heading"><h2>今日考勤状态</h2><button class="icon-button" type="button" @click="statusModal=false"><X :size="16" /></button></div><p class="modal-note">管理员可新增或删除所有状态，包括预置状态。删除后，已使用该状态的人员会切换为当前保留的第一个状态。</p><div class="status-add"><input v-model="newStatusLabel" placeholder="例如：外出培训" /><button class="primary-button" type="submit"><Plus :size="16" />新增状态</button></div><div class="status-list"><div v-for="option in statusOptions" :key="option.value"><span>{{option.label}}</span><small>可删除</small><button class="icon-button danger-button" type="button" title="删除状态" @click="removeStatus(option)"><Trash2 :size="16" /></button></div></div></form></div>
    <Transition name="toast"><div v-if="toast" class="toast"><Check :size="17" />{{toast}}<button type="button" @click="toast=''"><X :size="15" /></button></div></Transition>
  </div>
</template>
